-- MySQL migration: claims, encrypted bank details, and the user wallet ledger.
CREATE TABLE wallets (wallet_id INT AUTO_INCREMENT PRIMARY KEY, user_id INT NOT NULL UNIQUE, balance DECIMAL(12,2) NOT NULL DEFAULT 0, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, CONSTRAINT fk_wallet_user FOREIGN KEY (user_id) REFERENCES users(id));
CREATE TABLE wallet_transactions (wallet_transaction_id INT AUTO_INCREMENT PRIMARY KEY, wallet_id INT NOT NULL, type VARCHAR(30) NOT NULL, amount DECIMAL(12,2) NOT NULL, reference_id VARCHAR(64) NOT NULL UNIQUE, created_by INT NULL, description VARCHAR(255) NULL, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, INDEX idx_wallet_transactions_wallet_created (wallet_id, created_at), CONSTRAINT fk_wallet_transaction_wallet FOREIGN KEY (wallet_id) REFERENCES wallets(wallet_id));
CREATE TABLE claims (claim_id INT AUTO_INCREMENT PRIMARY KEY, user_id INT NOT NULL, wallet_id INT NOT NULL, request_id CHAR(36) NOT NULL, amount DECIMAL(12,2) NOT NULL, status ENUM('PENDING','PROCESSING','COMPLETED','FAILED') NOT NULL DEFAULT 'PENDING', razorpay_contact_id VARCHAR(64) NULL, razorpay_fund_account_id VARCHAR(64) NULL, razorpay_payout_id VARCHAR(64) NULL UNIQUE, payout_idempotency_key CHAR(36) NOT NULL UNIQUE, bank_account_last_four VARCHAR(4) NOT NULL, utr VARCHAR(64) NULL, failure_reason VARCHAR(255) NULL, reference_id VARCHAR(64) NOT NULL UNIQUE, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, INDEX idx_claims_user_created (user_id, created_at), UNIQUE KEY uq_claims_user_request (user_id, request_id), CONSTRAINT fk_claim_user FOREIGN KEY (user_id) REFERENCES users(id), CONSTRAINT fk_claim_wallet FOREIGN KEY (wallet_id) REFERENCES wallets(wallet_id));
CREATE TABLE claim_bank_accounts (id INT AUTO_INCREMENT PRIMARY KEY, user_id INT NOT NULL UNIQUE, encrypted_details TEXT NOT NULL, last_four VARCHAR(4) NOT NULL, updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, CONSTRAINT fk_claim_bank_user FOREIGN KEY (user_id) REFERENCES users(id));
